// Entry point of the game : runs the transpiled SCP:CB program (bbMain, generated by tools/bb2cpp) on the
// ported Blitz3D runtime.
#include "bbruntime.h"
#include "bbgame.h"
#include "gxruntime.h"
#include "wiiu_app.h"
#include "wiiu_debug.h"
#include "wiiu_prof.h"

#include <whb/log.h>

static int gameMain(){
	gxRuntime *rt=gxRuntime::openRuntime( "" );
	if( !rt ) return 0;
	bbInitData();
	WHBLogPrintf( "scpcb: runtime open, starting the game" );
	const char *err=bbruntime_run( rt,bbMain,false );
	if( err ) WHBLogPrintf( "scpcb: runtime error: %s",err );
	gxRuntime::closeRuntime( rt );
	return 0;
}

int main( int argc,char **argv ){
	wiiu::debugInit();
	wiiu::profInit();
	//the game runs on its own thread : the main thread's 64 KB stack is too small
	int ret=wiiu::appMain( gameMain );
	wiiu::debugShutdown();
	return ret;
}
